-- =====================================================================
-- ShopSphere — starter catalogue data (MySQL)
-- 6 stores, 6 departments + 25 subcategories, 77 products with photos,
-- gallery images and specifications, and one demo account per role.
--
-- Run AFTER Internship_Ecommerce.sql:
--   mysql -u root -p ecommerce_intern < DataBase/catalog_data.sql
-- The backend loads the same data automatically from
-- Backend/ecommerce/src/main/resources/seed/catalog.json when
-- app.seed.demo-data=true, so this file is only needed to fill the
-- database without starting the app. INSERT IGNORE makes it safe to re-run.
--
-- Demo account passwords are BCrypt hashes of the demo password
-- (Demo@12345); the backend resets them to app.demo.password on start.
-- The admin account is NOT included: it is created from the secrets file.
-- =====================================================================
USE ecommerce_intern;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET FOREIGN_KEY_CHECKS = 1;
